mapper.select:
SELECT RESP_ID
FROM (
    SELECT RESP_ID
    FROM TB_SURVEY_RESP_HDR
    WHERE CUST_CODE = #{custCode}
      AND SURVEY_ID = #{surveyId}
    ORDER BY RESP_ID DESC
)
WHERE ROWNUM = 1

mapper.delete:
DELETE FROM TB_CUST_RECO_TOP3
WHERE CUST_CODE = #{custCode}
  AND SURVEY_ID = #{surveyId}
